const input = $input.first().json;

// If the AI returned a JSON string inside "output" (Generate mode)
if (typeof input.output === 'string') {
  const start = input.output.indexOf('{');
  const end = input.output.lastIndexOf('}');

  if (start === -1 || end === -1) {
    throw new Error('No JSON found');
  }

  return [
    {
      json: JSON.parse(input.output.substring(start, end + 1)),
    },
  ];
}

// Otherwise (Update / Approve), the data is already JSON
return [
  {
    json: input,
  },
];

const item = $input.first();
const json = item.json;

const cleaned = (json.chatInput || "").trim();

const lower = cleaned.toLowerCase();

let command = null;
let comment = "";

if (lower.startsWith("approve")) {
  command = "approve";
} else if (lower.startsWith("update")) {
  command = "update";

  comment = cleaned
    .replace(/^update\s+/i, "")
    .replace(/[a-z]+-\d+/i, "")
    .trim();
}

// استخراج الـ Story Key سواء كانت حروف كبيرة أو صغيرة
const storyKeyMatch = cleaned.match(/[a-z]+-\d+/i);

const storyKey = storyKeyMatch
  ? storyKeyMatch[0].toUpperCase()
  : null;

return [
  {
    json: {
      ...json,
      chatInput: cleaned,
      command,
      storyKey,
      comment,
    },
  },
];

const data = $input.first().json;

// لو الـ AI رجع Object
if (typeof data.output !== 'string') {
  return [{
    json: data.output ?? data
  }];
}

// لو رجع String
const raw = data.output;

const start = raw.indexOf('{');
const end = raw.lastIndexOf('}');

if (start === -1 || end === -1) {
  throw new Error('No JSON found');
}

return [{
  json: JSON.parse(raw.substring(start, end + 1))
}];

const input = $input.all();

const msg = input[0].json;
const draft = input[1].json;

return [
  {
    json: {
      mode: "update",
      reviewerComment: msg.comment,
      currentDraft: draft
    }
  }
];
